/// <summary>Zero-reflection JSON string mapping for <see cref="Gift"/>.</summary>
internal static class GiftExtensions
{
	public static string ToJsonValue(this Gift value)
	{
		return value switch
		{
			Gift.NPPDRUSHTheMilkOfUltravioletCis => "//N.P.P.D. RUSH//- The milk of Ultraviolet_cis",
			Gift.V123KICKITDropThatBeatLikeAnUglyBaby => "1... 2... 3... KICK IT! (Drop That Beat Like an Ugly Baby)",
			Gift.V100AsianCatsDeluxeEdition => "100 Asian Cats Deluxe Edition",
			Gift.V100OrangeJuice => "100% Orange Juice",
			Gift.V100OrangeJuiceCis => "100% Orange Juice_cis",
			Gift.V12LaboursOfHercules => "12 Labours of Hercules",
			Gift.V12LaboursOfHerculesIITheCretanBull => "12 Labours of Hercules II: The Cretan Bull",
